import 'package:flutter/material.dart';import '../app.dart';import '../models/money_transaction.dart';import '../models/region_profile.dart';import '../services/local_store.dart';
class BudgetsPage extends StatelessWidget{final LocalStore store;final RegionProfile profile;const BudgetsPage({super.key,required this.store,required this.profile});
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Monthly Budgets')),body:AnimatedBuilder(animation:store,builder:(context,_){final now=DateTime.now();return ListView(padding:const EdgeInsets.all(16),children:expenseCategories.map((c){final limit=store.budgetFor(c);final spent=store.transactions.where((t)=>t.type==MoneyTransactionType.expense&&t.category==c&&t.date.year==now.year&&t.date.month==now.month).fold(0.0,(s,t)=>s+t.amount);final ratio=limit<=0?0.0:(spent/limit).clamp(0.0,1.0).toDouble();return Card(child:ListTile(title:Text(c),subtitle:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const SizedBox(height:6),LinearProgressIndicator(value:ratio),const SizedBox(height:5),Text(limit<=0?'No budget set':'${money(store,profile,spent)} of ${money(store,profile,limit)}')]),trailing:IconButton(icon:const Icon(Icons.edit_rounded),onPressed:()=>_edit(context,c,limit))));}).toList());}));
 Future<void> _edit(BuildContext context,String c,double current)async{final x=TextEditingController(text:current>0?current.toStringAsFixed(0):'');final v=await showDialog<double>(context:context,builder:(ctx)=>AlertDialog(title:Text('$c budget'),content:TextField(controller:x,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Monthly limit')),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,double.tryParse(x.text)??0),child:const Text('Save'))]));if(v!=null)await store.setBudget(c,v);}}
